<?php declare(strict_types=1);
use Kulturhus\Verein\{Finance,FinanceReports,DatevExport,PaymentFundingOriginals};

(static function(PDO$db,Closure$assert,Closure$denied,Closure$key):void{
    $positions=static function(array$rows):array{$out=[];foreach($rows as$row)$out[$row['position_id']]=($out[$row['position_id']]??0)+(int)$row['amount_cents'];ksort($out,SORT_STRING);return $out;};
    foreach(['income','expense']as$kind){
        $club='own-partial-cent-'.$kind;$actor=$club.'-admin';$db->prepare('INSERT INTO clubs VALUES(?,?)')->execute([$club,'Own partial original cents']);$db->prepare("INSERT INTO actors(id,club_id,role,is_superuser)VALUES(?,?,'member',1)")->execute([$actor,$club]);$f=new Finance($db,$actor);$account=$f->createAccount('Own partial original cents','offline','1000','2020-01-01');$parts=[];for($i=0;$i<3;$i++)$parts[]=['description'=>'Own original cent '.$i,'amount'=>'0.01','sphere'=>'1','account'=>$kind==='expense'?'68150':'40000','tax_rate'=>'0','input_tax'=>$kind==='expense'?'none':'unknown'];$entry=$f->createEntry(['kind'=>$kind,'category'=>'general','amount'=>'0.03','description'=>'Own three original position cents','document_date'=>'2026-01-01','due_date'=>'2026-01-01','positions'=>$parts],$key());$source=$f->createTransaction(['account'=>$account,'direction'=>$kind==='expense'?'expense':'income','amount'=>'0.03','booked_on'=>'2026-01-23','description'=>'Own actual three-cent original'],$key());
        foreach(['0.01','0.02']as$part)$f->allocate($source,(int)$f->transactionDetail($source)['version'],$entry,(int)$f->entry($entry)['version'],$part,$key());$links=$f->allocations($entry);foreach($links as$link)if((int)$link['cents']===2)$selected=$link['id'];$counter=$f->createTransaction(['account'=>$account,'direction'=>$kind==='expense'?'income':'expense','amount'=>'0.01','booked_on'=>'2026-01-24','description'=>'Own actual last original cent returned'],$key());$reporter=new FinanceReports($db,$actor);$before=$reporter->journal(['from'=>'2026-01-23','to'=>'2026-01-23']);$export=new DatevExport($db,$actor);$options=['from'=>'2026-01-23','to'=>'2026-01-23','advisor'=>'1001','client'=>'1','bank_codes'=>[$account=>'18000']];$originalBatch=$export->preview($options);$originalCsv=$export->download($options,$originalBatch['hash']);$amounts=[['allocation_id'=>$selected,'amount'=>'0.01']];$reason='Own last original cent returned; demand stays valid';$review=$f->partialReturnReview($counter,$amounts,$reason);$f->returnPaymentParts($counter,(int)$review['review']['counter']['version'],$amounts,$reason,$key(),$review['hash'],true);$negative=$reporter->journal(['from'=>'2026-01-24','to'=>'2026-01-24']);$returned=$positions($negative['rows']);$original=$positions($before['rows']);$assert(count($original)===3&&array_values($original)===[1,1,1]&&count($returned)===1&&array_key_first($returned)===$entry.':'.$review['review']['selected'][0]['ranges'][0][1]&&array_values($returned)===[1],'actual partial '.$kind.' last-cent return reverses precisely the last cent of its selected original allocation');$assert($before===$reporter->journal(['from'=>'2026-01-23','to'=>'2026-01-23'])&&$originalBatch===$export->preview($options),'actual partial '.$kind.' original journal and complete DATEV preview remain byte exact');$afterCsv=$export->download($options,$originalBatch['hash']);$assert(array_slice(explode("\r\n",$originalCsv),2)===array_slice(explode("\r\n",$afterCsv),2),'actual partial '.$kind.' keeps all earlier DATEV data bytes exact');$counterOptions=array_replace($options,['from'=>'2026-01-24','to'=>'2026-01-24']);$batch=$export->preview($counterOptions);$csv=$export->download($counterOptions,$batch['hash']);$valid=!$batch['errors'];foreach(array_filter(array_slice(explode("\r\n",substr($csv,3)),2))as$line){$columns=str_getcsv($line,';','"','');$valid=$valid&&count($columns)===125&&$columns[117]==='1'&&$columns[1]===($kind==='expense'?'H':'S');}$assert($valid,'actual partial '.$kind.' DATEV counter uses the original posting side with the explicit general reversal marker');
        $replacement=$f->createTransaction(['account'=>$account,'direction'=>$kind==='expense'?'expense':'income','amount'=>'0.01','booked_on'=>'2026-01-25','description'=>'Own actual returned cent recollected'],$key());$f->allocate($replacement,1,$entry,(int)$f->entry($entry)['version'],'0.01',$key());$replacementJournal=$reporter->journal(['from'=>'2026-01-25','to'=>'2026-01-25']);$assert($positions($replacementJournal['rows'])===$returned&&$before===$reporter->journal(['from'=>'2026-01-23','to'=>'2026-01-23']),'actual partial '.$kind.' normal recollection fills precisely the original last-position cent');
    }

    $blocked=0;
    foreach(['0.01','0.07','0.33','0.77','0.03']as$i=>$amount){
        $club='own-partial-vat-'.$i;$actor=$club.'-admin';$db->prepare('INSERT INTO clubs VALUES(?,?)')->execute([$club,'Own actual partial VAT source']);$db->prepare("INSERT INTO actors(id,club_id,role,is_superuser)VALUES(?,?,'member',1)")->execute([$actor,$club]);$f=new Finance($db,$actor);$account=$f->createAccount('Own actual VAT funding','offline','1000','2020-01-01');$entry=$f->createEntry(['kind'=>'income','category'=>'general','amount'=>($i===4?'0.06':'2.26'),'description'=>'Own original VAT position pair','document_date'=>'2026-01-01','due_date'=>'2026-01-01','positions'=>array_slice([['description'=>'Own original nineteen','amount'=>($i===4?'0.06':'1.19'),'tax_rate'=>'19','sphere'=>'3','account'=>'42030','booking_key'=>'3','input_tax'=>'unknown'],['description'=>'Own original seven','amount'=>'1.07','tax_rate'=>'7','sphere'=>'4','account'=>'42050','booking_key'=>'2','input_tax'=>'unknown']],0,$i===4?1:2)],$key());$source=$f->createTransaction(['account'=>$account,'direction'=>'income','amount'=>($i===4?'0.06':'2.26'),'booked_on'=>'2026-01-23','description'=>'Own actual original VAT payment'],$key());foreach(['0.01',$i===4?'0.05':'2.25']as$part)$f->allocate($source,(int)$f->transactionDetail($source)['version'],$entry,(int)$f->entry($entry)['version'],$part,$key());foreach($f->allocations($entry)as$link)if((int)$link['cents']===($i===4?5:225))$allocation=$link['id'];$counter=$f->createTransaction(['account'=>$account,'direction'=>'expense','amount'=>$amount,'booked_on'=>'2026-01-24','description'=>'Own actual partly returned VAT payment'],$key());$export=new DatevExport($db,$actor);$options=['from'=>'2026-01-23','to'=>'2026-01-23','advisor'=>'1001','client'=>'1','bank_codes'=>[$account=>'18000']];$original=$export->preview($options);$amounts=[['allocation_id'=>$allocation,'amount'=>$amount]];$reason='Own actual VAT part returned; original demand stays due';$review=$f->partialReturnReview($counter,$amounts,$reason);$f->returnPaymentParts($counter,(int)$review['review']['counter']['version'],$amounts,$reason,$key(),$review['hash'],true);$assert($original===$export->preview($options),'actual VAT partial '.$amount.' retains the entire earlier original DATEV preview');$counterOptions=array_replace($options,['from'=>'2026-01-24','to'=>'2026-01-24']);$batch=$export->preview($counterOptions);$rounding=array_filter($batch['errors'],static fn(array$row):bool=>str_contains($row['message'],'Steuer-Rundungsabweichung'));
        if($rounding){++$blocked;$denied(fn()=>$export->download($counterOptions,$batch['hash']),'actual VAT partial '.$amount.' cannot silently export a different automatic tax cent');}
        else{$csv=$export->download($counterOptions,$batch['hash']);$valid=true;foreach(array_filter(array_slice(explode("\r\n",substr($csv,3)),2))as$line){$columns=str_getcsv($line,';','"','');$valid=$valid&&$columns[117]==='1'&&$columns[1]==='S';}$assert($valid,'actual VAT partial '.$amount.' exports only exact tax slices with the original income reversal marker');}
    }
    $assert($blocked>0,'actual fractional VAT source exercises the meaningful DATEV rounding refusal rather than only exact easy cases');
})($db,$assert,$denied,$key);
